const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE = 0.1;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
};

function quotePremium(items: ItemInput[]): number {
  let policyBase = 0;
  let itemModifiers = 0;

  for (const item of items) {
    const base = BASE_PREMIUMS[item.type];
    policyBase += base;
    itemModifiers += base * FIRST_INSURANCE_SURCHARGE;
  }

  return policyBase + itemModifiers + PROCESSING_FEE;
}

export function runScenario(scenario: Scenario): ScenarioResult {
  return {
    results: scenario.steps.map((step) => ({ premium: quotePremium(step.items) })),
  };
}

