}

export interface ItemInput {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface QuoteStep {
  op: 'quote';
  items: ItemInput[];
}

export interface Scenario {
  customer: Customer;
  steps: QuoteStep[];
}

export interface QuoteResult {
  premium: number;
}

export interface ScenarioResult {
  results: QuoteResult[];
