}

function reimbursableAmount(damage: Damage): number {
  return damage.amount;
}

function settleClaim(policy: Policy, incident: Incident): ClaimResult {
  const desired = incident.damages.reduce(
    (sum, damage) => sum + Math.max(0, reimbursableAmount(damage) - DEDUCTIBLE),
